{
  "root": "main",
  "state": {
    "checklist": [
      { "step": "Keep rent notice, lease, and receipt proof" },
      { "step": "Save full payment history" },
      { "step": "Archive all related correspondence" },
      { "step": "Verify lease start: 2025-08-15" },
      { "step": "Verify notice date: 2026-02-01" },
      { "step": "Verify effective date: 2026-04-01" },
      { "step": "Verify increase percentage: 9%" }
    ],
    "incompletenessSigns": [
      { "issue": "Missing rent amounts" },
      { "issue": "Missing effective date" },
      { "issue": "Missing calculation basis" },
      { "issue": "Missing referenced documents" },
      { "issue": "Missing landlord contact info" },
      { "issue": "Vague wording" },
      { "issue": "Conflicts with lease" }
    ]
  },
  "elements": {
    "main": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "md", "padding": 16 },
      "children": ["title", "intro", "checklistTable", "incompletenessTable", "draftSection", "actions", "sources"]
    },
    "title": { "type": "Text", "props": { "text": "Toronto Rent Increase Notice: Calm Response Checklist", "variant": "h1" }, "children": [] },
    "intro": { "type": "Text", "props": { "text": "A calm reply works best when it is short, factual, and focused on records, dates, and clarity.", "variant": "body" }, "children": [] },
    "checklistTable": {
      "type": "Table",
      "props": {
        "title": "General Checklist",
        "columns": [{ "key": "step", "label": "Action Item" }],
        "statePath": "/checklist",
        "domain": "status",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "incompletenessTable": {
      "type": "Table",
      "props": {
        "title": "Signs of Incomplete Notice",
        "columns": [{ "key": "issue", "label": "Potential Issue" }],
        "statePath": "/incompletenessSigns",
        "domain": "status",
        "preferredPresentation": "cards"
      },
      "children": []
    },
    "draftSection": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["draftTitle", "draftBody"]
    },
    "draftTitle": { "type": "Text", "props": { "text": "Polite Email Draft", "variant": "h2" }, "children": [] },
    "draftBody": { "type": "Text", "props": { "text": "Subject: Questions About the Rent Increase Notice. Thank you for sending the notice dated February 1, 2026. I am reviewing my records and wanted to confirm the current rent amount, the new monthly rent, the effective date, and whether there is any additional document I should review. I also wanted to check whether the notice is complete as sent, since I want to make sure I keep accurate records and follow the right process. Best regards, [Tenant Name].", "variant": "body" }, "children": [] },
    "actions": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["btn1", "btn2", "btn3"]
    },
    "btn1": { "type": "Button", "props": { "label": "Save records", "openUrl": "https://www.canada.ca/en/services/taxes/tool.html" }, "children": [] },
    "btn2": { "type": "Button", "props": { "label": "Review lease", "openUrl": "https://www.ontario.ca/page/renting-ontario-your-rights" }, "children": [] },
    "btn3": { "type": "Button", "props": { "label": "Draft reply", "openUrl": "https://www.grammarly.com/blog/email-templates/" }, "children": [] },
    "sources": {
      "type": "Stack",
      "props": { "direction": "vertical", "gap": "sm" },
      "children": ["src1", "src2"]
    },
    "src1": { "type": "Button", "props": { "label": "Ontario tenant information", "variant": "borderless", "openUrl": "https://www.ontario.ca/page/renting-ontario-your-rights" }, "children": [] },
    "src2": { "type": "Button", "props": { "label": "Government of Canada consumer guidance", "variant": "borderless", "openUrl": "https://www.canada.ca/en/services/finance/consumer-affairs.html" }, "children": [] }
  }
}
